cd /app; cat > /tmp/fuzz.py <<'EOF'
import json,random,subprocess,os,tempfile,sys
random.seed(int(sys.argv[1]))
def run(root,args):
    r=subprocess.run([sys.executable,"-m","meterbill"]+args,cwd=root,capture_output=True,text=True)
    return r.returncode,r.stdout,r.stderr
def dec(n): return str(random.choice([random.randint(0,999)/10**n, random.randint(0,99999)/10**(n+2)])) 
bad=0
for it in range(60):
    d=tempfile.mkdtemp()
    cashes=random.choice([["none","whole","0.05","0.10","0.5","1"]])
    book={"currencies":{"C%d"%i:{"cash":c} for i,c in enumerate(cashes)},"tariffs":{}}
    for t in range(3):
        ups=sorted(random.sample(range(10,500),2))
        book["tariffs"]["t%d"%t]={"currency":"C%d"%random.randrange(len(cashes)),"vat":random.choice(["0.21","0.055","0.125","0.0725","0","0.2"]),
          "standing":"%.4f"%random.choice([0.411,0.125,0.05,0.0025,0.1]),
          "bands":[{"upto":str(ups[0]),"price":"%.4f"%random.choice([0.125,0.25,0.1275,0.0125,0.205])},{"upto":str(ups[1]),"price":"%.3f"%random.choice([0.125,0.2,0.0375])},{"upto":None,"price":random.choice(["0.5","0.0625","0.3333"])}]}
    bp=d+"/book.json"; json.dump(book,open(bp,"w"))
    os.mkdir(d+"/acc")
    for i in range(6):
        segs=[]
        acc={"account":"A%d"%i,"name":"n","tariff":"t%d"%random.randrange(3),"period":{"start":"2026-03-01","end":"2026-03-%02d"%random.randint(10,31)},
          "readings":[{"meter":"M","kwh":str(random.choice([random.randint(0,6000)/10,random.randint(0,60000)/100,random.randint(0,6000)/8]))}],
          "credits":[{"ref":"c%d"%j,"amount":random.choice([-4.25,1.005,2.675,0.125,random.uniform(-9,9),-0.004,3,1e-9]),"note":""} for j in range(random.randint(0,3))]}
        if random.random()<.5:
            acc["standing"]=[{"from":"2026-03-01","to":"2026-03-10","rate":"0.4110"},{"from":"2026-03-11","to":acc["period"]["end"],"rate":random.choice(["0.0333","0.1250","0"])}]
        json.dump(acc,open(d+"/acc/a%d.json"%i,"w"))
    cmds=[["tariffs"],["batch",d+"/acc"],["batch",d+"/acc","--format","csv"],["batch",d+"/acc","--workers","1"]]
    for i in range(6):
        for f in ["text","json","csv"]: cmds.append(["bill",d+"/acc/a%d.json"%i,"--format",f])
    for _ in range(6):
        cmds.append(["quote","t%d"%random.randrange(3),str(random.choice([random.randint(0,9000)/100,random.randint(0,900),random.randint(0,90000)/8])),str(random.randint(1,40)),"--format",random.choice(["text","json"])])
    for c in cmds:
        a=run("/tmp/orig",["--tariffs",bp]+c); b=run("/app",["--tariffs",bp]+c)
        if a!=b: bad+=1; print("DIFF",c,a[1][:300],b[1][:300],a[2][-200:],b[2][-200:])
print("bad",bad)
EOF
